INSERT INTO `content` (`id`, `data`) VALUES ('main', '{"theme":"warm","trust":{"name":"Mumbai Meghwal Panchayat","nameGu":"મુંબઈ મેઘવાલ પંચાયત","subtitle":"MMP","phone":"+919769213507","email":"mmpcwc13507@gmail.com","address":"C/O , B-4, Sant Veer Meghmaya Marg, Tulsiwadi, Mahalaxmi, Mumbai 400034","hours":"Mon–Sat: 6:00 PM– 9:00 PM","estd":"","reg80G":"","panNo":"","cin":"","logo":{"visible":true,"type":"image","text":"MMP","url":"https://firebasestorage.googleapis.com/v0/b/mmp-cwc-new.firebasestorage.app/o/logos%2Flogo_1786439598300.png?alt=media&token=0be4d201-7448-45de-84ae-9c7ce87c7a87","size":50,"shape":"circle","bgColor":"transparent"},"adminHeader":"Mumbai Meghwal Panchayat","topBarNotice":"   "},"headerAction":{"mode":"dashboard","label":"Dashboard","labelGu":"ડેશબોર્ડ","linkTarget":""},"hero":{"badge":"COMMUNITY PLATFORM","title":"Empowering Our Community Together","titleGu":"આપણા સમુદાયને સાથે મળીને સશક્તિકરણ","subtitle":"The Mumbai Meghwal Panchayat is a prominent, caste-based community organization representing the Gujarati Meghwal community in Mumbai.","showTopBanner":true,"topBanner":"https://firebasestorage.googleapis.com/v0/b/mmp-cwc-new.firebasestorage.app/o/gallery%2Fphoto_1786439667571.png?alt=media&token=87ce8f94-560c-481e-ab6d-7b41966ef11a","topBannerHeight":149,"showRegBtn":true,"regBtnLabel":"Education Form Registration","regBtnLink":"#event-0","subtitleGu":"મુંબઈ મેઘવાળ પંચાયત એ મુંબઈમાં રહેતા ગુજરાતી મેઘવાળ જ્ઞાતિનું પ્રતિનિધિત્વ કરતી અગ્રણી સામાજિક સંસ્થા છે.","cta1":"","cta1Gu":"","cta2":"","cta2Gu":"","badge1":"","badge2":"","badge3":"","showStats":false,"showImage":false,"image":"https://firebasestorage.googleapis.com/v0/b/vdiyagohilcharitable.firebasestorage.app/o/gallery%2Fphoto_1784962387597.png?alt=media&token=1e0d8fa3-723a-42a3-b878-09acf74d54ce","regBtnLabelGu":"હવે નોંધણી કરો","bgCss":"#FFDF00","textColor":"#000000","heroType":"slider","sliderImages":["data:image/png;base64,","data:image/png;base64,","data:image/jpeg;base64,","data:image/png;base64,","data:image/jpeg;base64,"],"imageFit":"cover","imageWidth":700,"imageMaxHeight":290,"badgeBgColor":"#213d47"},"stats":[{"num":"10,000+","label":"Members","labelGu":"સભ્યો"},{"num":"$100k","label":"Funds Raised","labelGu":"ભંડોળ એકત્ર"},{"num":"50+","label":"Volunteers","labelGu":"સ્વયંસેવકો"},{"num":"10","label":"Active Programs","labelGu":"સક્રિય કાર્યક્રમો"}],"about":{"heading":"Rooted in Compassion, Driven by Purpose","headingGu":"કરુણામાં મૂળ, ઉદ્દેશ્ય દ્વારા ચાલિત","body1":"myCommunity was founded to create a dignified life for every individual regardless of caste, creed, or economic status. This is fallback data when Firebase is not connected.","body1Gu":"મારો સમુદાય દરેક વ્યક્તિ માટે સન્માનજનક જીવન બનાવવા માટે સ્થાપિત કરવામાં આવ્યો હતો.","body2":"Our work spans education, healthcare, and empowerment through community participation.","body2Gu":"અમારું કાર્ય શિક્ષણ, આરોગ્ય અને સશક્તિકરણ સુધી ફેલાયેલું છે.","points":["Transparent Governance","Community-Led Programs","Annual Public Audit","Zero Admin Fee Policy"],"yearsLabel":"Years of Service","cta":"Read Our Story","pointsGu":["","","",""],"story":"<p></p>","storyGu":"<p></p>"},"programs":[{"icon":"📚","title":"Education for All","sub":"Scholarships and learning centers for underprivileged children","details":"<p>###&nbsp;Our&nbsp;Mission&nbsp;Our&nbsp;Education&nbsp;for&nbsp;All&nbsp;initiative&nbsp;focuses&nbsp;on&nbsp;providing&nbsp;quality&nbsp;education&nbsp;to&nbsp;children&nbsp;from&nbsp;marginalized&nbsp;communities.&nbsp;###&nbsp;What&nbsp;We&nbsp;Do&nbsp;-&nbsp;**Evening&nbsp;Centers**:&nbsp;We&nbsp;run&nbsp;evening&nbsp;learning&nbsp;centers&nbsp;for&nbsp;over&nbsp;500&nbsp;children.&nbsp;-&nbsp;**Scholarships**:&nbsp;We&nbsp;offer&nbsp;merit-based&nbsp;scholarships&nbsp;to&nbsp;help&nbsp;students&nbsp;pursue&nbsp;higher&nbsp;education.&nbsp;-&nbsp;**Free&nbsp;Supplies**:&nbsp;Distribute&nbsp;free&nbsp;school&nbsp;supplies,&nbsp;uniforms,&nbsp;and&nbsp;textbooks.&nbsp;&gt;&nbsp;*&quot;Education&nbsp;is&nbsp;the&nbsp;most&nbsp;powerful&nbsp;weapon&nbsp;which&nbsp;you&nbsp;can&nbsp;use&nbsp;to&nbsp;change&nbsp;the&nbsp;world.&quot;*</p>","color":"#FFF4EC","border":"#FDDBB8","titleGu":"","subGu":"","detailsGu":"<p></p>"},{"icon":"🏥","title":"Health and Wellness","sub":"Free medical camps, medicines and health awareness drives","details":"<p>###&nbsp;Healthcare&nbsp;for&nbsp;Everyone&nbsp;We&nbsp;organize&nbsp;monthly&nbsp;free&nbsp;medical&nbsp;camps&nbsp;in&nbsp;rural&nbsp;areas,&nbsp;offering:&nbsp;1.&nbsp;General&nbsp;physical&nbsp;checkups&nbsp;2.&nbsp;Eye&nbsp;and&nbsp;dental&nbsp;exams&nbsp;3.&nbsp;Free&nbsp;basic&nbsp;medicines&nbsp;Our&nbsp;health&nbsp;awareness&nbsp;drives&nbsp;educate&nbsp;communities&nbsp;on&nbsp;hygiene,&nbsp;nutrition,&nbsp;and&nbsp;preventative&nbsp;care.</p>","color":"#E8F4F8","border":"#B8D8E8","titleGu":"","subGu":"","detailsGu":"<p></p>"},{"icon":"🌾","title":"Livelihood Support","sub":"Skill development and micro-finance for rural communities","details":"<p>###&nbsp;Economic&nbsp;Independence&nbsp;To&nbsp;foster&nbsp;economic&nbsp;independence,&nbsp;we&nbsp;provide&nbsp;skill&nbsp;development&nbsp;workshops&nbsp;in:&nbsp;-&nbsp;**Tailoring&nbsp;&amp;&nbsp;Sewing**&nbsp;-&nbsp;**Computer&nbsp;Literacy**&nbsp;-&nbsp;**Basic&nbsp;Mechanics**&nbsp;We&nbsp;also&nbsp;offer&nbsp;micro-finance&nbsp;support&nbsp;to&nbsp;help&nbsp;families&nbsp;start&nbsp;small&nbsp;sustainable&nbsp;businesses.</p>","color":"#EDFAF1","border":"#B8E8CC","titleGu":"","subGu":"","detailsGu":"<p></p>"},{"icon":"🤝","title":"Women Empowerment","sub":"Self-help groups, vocational training and legal aid","details":"<p>###&nbsp;Empowering&nbsp;Women&nbsp;Our&nbsp;Women&nbsp;Empowerment&nbsp;programs&nbsp;create&nbsp;**self-help&nbsp;groups**&nbsp;where&nbsp;women&nbsp;can&nbsp;save&nbsp;and&nbsp;invest&nbsp;together.&nbsp;We&nbsp;offer&nbsp;specialized&nbsp;vocational&nbsp;training&nbsp;and&nbsp;free&nbsp;legal&nbsp;aid&nbsp;to&nbsp;ensure&nbsp;women&nbsp;are&nbsp;aware&nbsp;of&nbsp;and&nbsp;can&nbsp;protect&nbsp;their&nbsp;rights.</p>","color":"#F9F0FF","border":"#D8B8E8","titleGu":"","subGu":"","detailsGu":"<p></p>"},{"icon":"🌊","title":"Disaster Relief","sub":"Rapid response support for flood and earthquake victims","details":"<p>###&nbsp;Emergency&nbsp;Response&nbsp;In&nbsp;times&nbsp;of&nbsp;natural&nbsp;calamities,&nbsp;our&nbsp;rapid&nbsp;response&nbsp;teams&nbsp;distribute:&nbsp;-&nbsp;Emergency&nbsp;ration&nbsp;kits&nbsp;-&nbsp;Clean&nbsp;drinking&nbsp;water&nbsp;-&nbsp;Temporary&nbsp;shelter&nbsp;materials&nbsp;We&nbsp;work&nbsp;closely&nbsp;with&nbsp;local&nbsp;authorities&nbsp;to&nbsp;ensure&nbsp;aid&nbsp;reaches&nbsp;the&nbsp;most&nbsp;affected&nbsp;areas&nbsp;quickly.</p>","color":"#FEF9EC","border":"#F5E8B8","titleGu":"","subGu":"","detailsGu":"<p></p>"},{"icon":"🌱","title":"Environment","sub":"Tree plantation drives and clean water initiatives","details":"<p>###&nbsp;A&nbsp;Greener&nbsp;Future&nbsp;Committed&nbsp;to&nbsp;a&nbsp;greener&nbsp;future,&nbsp;we&nbsp;conduct&nbsp;regular&nbsp;**tree&nbsp;plantation&nbsp;drives**&nbsp;and&nbsp;maintain&nbsp;them&nbsp;with&nbsp;community&nbsp;support.&nbsp;We&nbsp;also&nbsp;install&nbsp;water&nbsp;purification&nbsp;systems&nbsp;in&nbsp;schools&nbsp;and&nbsp;villages&nbsp;to&nbsp;ensure&nbsp;access&nbsp;to&nbsp;safe&nbsp;drinking&nbsp;water.</p>","color":"#EDFAF1","border":"#B8E8CC","titleGu":"","subGu":"","detailsGu":"<p></p>"}],"events":[{"id":"ev_1785425112515","title":"Education felicitation 2026","date":"Oct - 02","month":"2026","location":"Mumbai","tag":"Education","color":"#E8F4F8","formId":"form_1785425256968","section":"Education 2026","issueCertificates":true,"issueInviteLetters":true,"titleGu":"","locationGu":"","dateGu":"","monthGu":"","tagGu":"","waGroupLink":"https://chat.whatsapp.com/FANjUcZMZsl50fypMuaqN1","waGroupQrCode":"data:image/jpeg;base64,","regClosed":true,"regClosedMsg":"This Link has ben closed,  Last day of form submissi