INSERT INTO `registrations` (`id`, `data`) VALUES ('1aQk3zEsEk7eUNGSTlsK', '{"Transaction ID":"GST-218408-59","transactionId":"GST-218408-59","Status":"Approved","Remarks":"","Full Name":"PREMJIBHAI PATEL","Participant Name":"PREMJIBHAI PATEL","Name":"PREMJIBHAI PATEL","Mobile":"9767968410","Mobile Number":"9767968410","Email":"","Address":"","Designation":"PRESIDENT","Organization":"PRESIDENT","Group":"Vibhag Pramukh, 64 POONA","Category":"Vibhag Pramukh, 64 POONA","Vibhag":"64 POONA","Vibhag Name":"64 POONA","Vibhag_Name":"64 POONA","vibhag":"64 POONA","groups":["Vibhag Pramukh","64 POONA"],"Groups":["Vibhag Pramukh","64 POONA"],"formId":"global_guest_directory_import","_collection":"contacts","eventId":"ev_internal_1787674161506","eventName":"Education Committee","eventTitle":"Education Committee","status":"Approved","isSpecialGuest":true,"globalGuestId":"cIqYEyDJuSzrhnMCAW8B","targetTemplateId":"doc_1789040345854","assignedDocTypes":["doc_1789040345854"],"deleted":true,"deletedAt":"2026-09-11T13:03:32.631Z","deletedBy":"pradeepparmar902@yahoo.com","isInviteMode":true,"activeDocTpl":{"id":"doc_1789040345854","name":"MMP President","icon":"🎟️","bgUrl":"","targetSection":"invites","customTpl":{"id":"doc_1789040345854","name":"MMP President","targetSection":"invites","targetAudience":"assigned","bgUrl":"","map":{},"fontSize":30,"fontColor":"#000000","type":"custom","orientation":"portrait","bgFit":"letterhead"}},"Vibhag New":"64 POONA","vibhagScope":"auto","customDocId":"doc_1789040345854","logHistory":[{"timestamp":"2026-09-11T15:11:02.580Z","actor":"pradeepparmar902@yahoo.com","action":"WhatsApp Sent: Official Invitation Pass","type":"whatsapp","messageType":"Official Invitation Pass","messageContent":"🏛️ *MUMBAI MEGHWAL PANCHAYAT*\\n🏆 *Education Committee*\\n═══════════════════════\\n\\n\\n🌷|| મુંબઈ મેઘવાળ પંચાયત ||🌷\\n                   [NGO]\\n     •••  સેન્ટ્રલ વર્કિંગ કમિટિ •••\\n 𑁍〰️〰️〰️〰️〰️〰️〰️𑁍\\n   || 🪷 વ્હોટ્સએપ જાહેરાત 🪷 ||\\n\\nવિષય: *મેઘ વિદ્યાર્થી ગુ