INSERT INTO `registrations` (`id`, `data`) VALUES ('bmN40c2Waj2XbbhxiYEA', '{"Transaction ID":"GST-217822-39","transactionId":"GST-217822-39","Status":"Approved","Remarks":"","Full Name":"SHAMJIBHAI BORICHA","Participant Name":"SHAMJIBHAI BORICHA","Name":"SHAMJIBHAI BORICHA","Mobile":"9137315118","Mobile Number":"9137315118","Email":"","Address":"","Designation":"PRESIDENT","Organization":"PRESIDENT","Group":"Vibhag Pramukh, 43 NAV BHARAT SOCIETY","Category":"Vibhag Pramukh, 43 NAV BHARAT SOCIETY","Vibhag":"43 NAV BHARAT SOCIETY","Vibhag Name":"43 NAV BHARAT SOCIETY","Vibhag_Name":"43 NAV BHARAT SOCIETY","vibhag":"43 NAV BHARAT SOCIETY","groups":["Vibhag Pramukh","43 NAV BHARAT SOCIETY"],"Groups":["Vibhag Pramukh","43 NAV BHARAT SOCIETY"],"formId":"global_guest_directory_import","_collection":"contacts","eventId":"ev_internal_1787674161506","eventName":"Education Committee","eventTitle":"Education Committee","status":"Approved","isSpecialGuest":true,"globalGuestId":"Z85KJ0Cby78hs3it6agU","targetTemplateId":"doc_1789040345854","assignedDocTypes":["doc_1789040345854"],"deleted":true,"deletedAt":"2026-09-11T13:03:59.386Z","deletedBy":"pradeepparmar902@yahoo.com","isInviteMode":true,"activeDocTpl":{"id":"doc_1789040345854","name":"MMP President","icon":"🎟️","bgUrl":"","targetSection":"invites","customTpl":{"id":"doc_1789040345854","name":"MMP President","targetSection":"invites","targetAudience":"assigned","bgUrl":"","map":{},"fontSize":30,"fontColor":"#000000","type":"custom","orientation":"portrait","bgFit":"letterhead"}},"Vibhag New":"43 NAV BHARAT SOCIETY","vibhagScope":"auto","customDocId":"doc_1789040345854","logHistory":[{"timestamp":"2026-09-11T15:12:27.964Z","actor":"pradeepparmar902@yahoo.com","action":"WhatsApp Sent: Official Invitation Pass","type":"whatsapp","messageType":"Official Invitation Pass","messageContent":"🏛️ *MUMBAI MEGHWAL PANCHAYAT*\\n🏆 *Education Committee*\\n═══════════════════════\\n\\n\\n🌷|| મુંબઈ મેઘવાળ પંચાયત ||🌷\\n                   [NGO]\\n     •••  સેન્ટ્રલ વર્કિંગ કમિટિ •••\\n 𑁍〰️〰️〰️〰️〰️〰️〰️𑁍\\n   || 🪷 વ્હોટ્સએપ જાહેરાત 🪷 ||\\n\\nવિષય: *મેઘ વિદ્યાર્થી ગુણ ગૌરવ પુરસ્કાર ૨૦૨૬* - ૨ ઓક્ટોબર,૨૦૨૬ બાબતે\\n\\nNamaste *SHAMJIBHAI BORICHA*\\nPRESIDENT\\n43 NAV BHARAT SOCIETY\\n\\nજય વીર મેઘમાયા,\\n\\nસવિનય જણાવવાનું કે, \\"મેઘ વિદ્યાર્થી ગુણ ગૌરવ પુરસ્કાર - ૨૦૨૬\\" અંતર્ગત આપના વિભાગ 43 NAV BHARAT SOCIETY માંથી અત્યાર સુધીમાં કુલ *0* વિદ્યાર્થીઓના ફોર્મ પ્રાપ્ત  થયા છે .\\n\\n    આ અંગે આપશ્રીને નમ્ર વિનંતી છે કે, આપના વિભાગના બાકી રહેતા તમામ પાત્ર વિદ્યાર્થીઓના ફોર્મ વહેલામાં વહેલી તકે ઓનલાઈન અથવા સેવક કાર્યાલય ખાતે મોકલી આપવા વિનંતી.\\n\\n   સાથોસાથ, આ શૈક્ષણિક સેવાના મહાયજ્ઞને સફળ બનાવવા માટે આપ સૌ પદાધિકારીશ્રીઓ તરફથી યથાયોગ્ય દાન / આર્થિક સહયોગ મળી રહે તેવી આગ્રહભરી વિનંતી સહ...\\n\\nઆભાર સહ,\\nલિ.\\n*વિનોદ જીવાભાઈ મકવાણા* Mob 9820582546\\nમહામંત્રી - ટ્રસ્ટી , સે.વ.ક.\\n\\n*પ્રદિપ કરસનભાઈ પરમાર* Mob 9819984437\\nચેરમેન - શિક્ષણ સમિતિ, સે. વ. ક.\\n\\n📞 Helpline: +919769213507 \\nhttps://www.mmp-cwc.com\\n\\n*### Student List As on  11-09-2026, 08:42 pm ###*\\n📋 *Registered List (43 NAV BHARAT SOCIETY):* No registrations found for this Vibhag.\\n\\n","remarks":"WhatsApp invitation pass (Official Invitation Pass) sent to applicant."}],"whatsAppCount":1,"lastWhatsAppType":"Official Invitation Pass","lastWhatsAppAt":"2026-09-11T15:12:27.964Z","lastWhatsAppContent":"🏛️ *MUMBAI MEGHWAL PANCHAYAT*\\n🏆 *Education Committee*\\n═══════════════════════\\n\\n\\n🌷|| મુંબઈ મેઘવાળ પંચાયત ||🌷\\n                   [NGO]\\n     •••  સેન્ટ્રલ વર્કિંગ કમિટિ •••\\n 𑁍〰️〰️〰️〰️〰️〰️〰️𑁍\\n   || 🪷 વ્હોટ્સએપ જાહેરાત 🪷 ||\\n\\nવિષય: *મેઘ વિદ્યાર્થી ગુણ ગૌરવ પુરસ્કાર ૨૦૨૬* - ૨ ઓક્ટોબર,૨૦૨૬ બાબતે\\n\\nNamaste *SHAMJIBHAI BORICHA*\\nPRESIDENT\\n43 NAV BHARAT SOCIETY\\n\\nજય વીર મેઘમાયા,\\n\\nસવિનય જણાવવાનું કે, \\"મેઘ વિદ્યાર્થી ગુણ ગૌરવ પુરસ્કાર - ૨૦૨૬\\" અંતર્ગત આપના વિભાગ 43 NAV BHARAT SOCIETY માંથી અત્યાર સુધીમાં કુલ *0* વિદ્યાર્થીઓના ફોર્મ પ્રાપ્ત  થયા છે .\\n\\n    આ અંગે આપશ્રીને નમ્ર વિનંતી છે કે, આપના વિભાગના બાકી રહેતા 